"""Token-bucket rate limiter for gwlib."""


class TokenBucket:
    """A single token-bucket for one client."""

    def __init__(self, capacity, refill_per_sec, clock):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        if refill_per_sec < 0:
            raise ValueError("refill_per_sec must be non-negative")
        self.capacity = capacity
        self.refill_per_sec = refill_per_sec
        self.clock = clock
        self.tokens = float(capacity)
        self._last_refill = clock.now()

    def allow(self, cost=1):
        """Refill, then consume `cost` tokens if available.

        Returns True if the request is allowed, False otherwise.
        """
        if cost <= 0:
            raise ValueError("cost must be positive")
        now = self.clock.now()
        elapsed = now - self._last_refill
        self._last_refill = now
        self.tokens = min(
            float(self.capacity),
            self.tokens + self.refill_per_sec * elapsed,
        )
        if self.tokens >= cost:
            self.tokens -= cost
            return True
        return False


class RateLimiter:
    """Manages one TokenBucket per client."""

    def __init__(self, capacity, refill_per_sec, clock):
        self.capacity = capacity
        self.refill_per_sec = refill_per_sec
        self.clock = clock
        self._buckets = {}

    def check(self, client, cost=1):
        """Return allow(cost) for the given client's bucket.

        The bucket is created (full) on first use.
        """
        if client not in self._buckets:
            self._buckets[client] = TokenBucket(
                self.capacity, self.refill_per_sec, self.clock
            )
        return self._buckets[client].allow(cost)
